export function solve(hetu: string): boolean {
  // Format: DDMMYY, century sign, 3-digit individual number, check character
  const match = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})([0-9A-Z])$/.exec(hetu);
  if (!match) {
    return false;
  }

  const [, dd, mm, yy, sign, nnn, check] = match;

  // Century from sign: '+' = 1800s, '-' = 1900s, 'A'/'a' = 2000s
  const centuries: Record<string, number> = { "+": 1800, "-": 1900, A: 2000, a: 2000 };
  const century = centuries[sign];
  if (century === undefined) {
    return false;
  }

  const day = Number(dd);
  const month = Number(mm);
  const year = century + Number(yy);

  // Validate month and day
  if (month < 1 || month > 12) {
    return false;
  }

  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > daysInMonth[month - 1]) {
    return false;
  }

  // Check character: DDMMYYZZZ mod 31 mapped onto the control alphabet
  const CONTROL = "0123456789ABCDEFHJKLMNPRSTUVWXY";
  const num = Number(dd + mm + yy + nnn); // 9 digits, safely within Number precision
  const expected = CONTROL[num % 31];

  return expected === check;
}

export function solve(cnp: string): boolean {
  // Exactly 13 ASCII digits
  if (!/^\d{13}$/.test(cnp)) {
    return false;
  }

  // Codes starting with 9000 are accepted without further checks
  if (cnp.startsWith("9000")) {
    return true;
  }

  const d = cnp.split("").map(Number);
  const first = d[0];
  const yy = d[1] * 10 + d[2];
  const mm = d[3] * 10 + d[4];
  const dd = d[5] * 10 + d[6];

  // Determine the full year from the century indicator
  let year: number;
  if (first === 1 || first === 2) {
    year = 1900 + yy;
  } else if (first === 3 || first === 4) {
    year = 1800 + yy;
  } else if (first === 5 || first === 6) {
    year = 2000 + yy;
  } else {
    // 0, 7, 8, 9: only the two-digit year is used.
    // Gregorian leap rule on yy gives the same result as "yy divisible by 4"
    // (yy = 0 is divisible by 400, so it is a leap year).
    year = yy;
  }

  const isLeap = (y: number): boolean =>
    (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;

  const daysInMonth = [
    31,
    isLeap(year) ? 29 : 28,
    31, 30, 31, 30, 31, 31, 30, 31, 30, 31,
  ];

  if (mm < 1 || mm > 12) {
    return false;
  }
  if (dd < 1 || dd > daysInMonth[mm - 1]) {
    return false;
  }

  // Check digit: weighted sum of digits 1-12, mod 11, remainder 10 becomes 1
  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += d[i] * weights[i];
  }
  let check = sum % 11;
  if (check === 10) {
    check = 1;
  }

  return check === d[12];
}

export function solve(id: string): boolean {
  const match = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!match) return false;

  const yy = Number(match[1]);
  let mm = Number(match[2]);
  const dd = Number(match[3]);
  const suffix = match[4];

  let year: number;
  if (suffix.length === 4) {
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  } else {
    // Numbers issued before 1954: 3 digit suffix
    if (yy >= 54) return false;
    if (suffix === "000") return false;
    year = 1900 + yy;
  }

  // Woman's month has 50 added
  if (mm > 50) mm -= 50;
  // From 2004 on, 20 may also be added
  if (mm > 20) {
    if (year < 2004) return false;
    mm -= 20;
  }
  if (mm < 1 || mm > 12) return false;

  // Validate the date exists
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  if (suffix.length === 4) {
    const digits = match[1] + match[2] + match[3] + suffix; // 10 digits
    const first9 = Number(digits.slice(0, 9));
    const last = Number(digits.slice(9));

    if (year < 1986 && first9 % 11 === 10 && last === 0) return true;

    return Number(digits) % 11 === 0;
  }

  return true;
}

export function solve(code: string): boolean {
  if (typeof code !== "string" || code.length !== 16) return false;

  const s = code.toUpperCase();
  const isLetter = (c: string): boolean => c >= "A" && c <= "Z";
  const isDigit = (c: string): boolean => c >= "0" && c <= "9";
  const OMO = "LMNPQRSTUV";
  const VOWELS = "AEIOU";

  // Name code: consonants, then vowels, then X padding.
  // phase 0 = consonants (X counts as consonant), 1 = vowels, 2 = padding (only X)
  const checkName = (part: string): boolean => {
    let phase = 0;
    for (let i = 0; i < part.length; i++) {
      const c = part[i];
      if (!isLetter(c)) return false;
      const isVowel = VOWELS.indexOf(c) >= 0;
      if (phase === 0) {
        if (isVowel) phase = 1;
      } else if (phase === 1) {
        if (c === "X") phase = 2;
        else if (!isVowel) return false;
      } else {
        if (c !== "X") return false;
      }
    }
    return true;
  };

  if (!checkName(s.slice(0, 3)) || !checkName(s.slice(3, 6))) return false;

  // Normalize omocodia letters at digit positions to digit characters.
  const chars: string[] = s.split("");
  const digitPositions = [6, 7, 9, 10, 12, 13, 14];
  for (const i of digitPositions) {
    const c = chars[i];
    if (isDigit(c)) continue;
    const k = OMO.indexOf(c);
    if (k < 0) return false;
    chars[i] = String(k);
  }

  // Month letter
  const MONTHS = "ABCDEHLMPRST";
  const month = MONTHS.indexOf(chars[8]) + 1;
  if (month === 0) return false;

  // Year and leap-year check (two-digit year, 00 divisible by 4)
  const yy = parseInt(chars[6] + chars[7], 10);
  const leap = yy % 4 === 0;

  // Day (1-31 for men, 41-71 for women)
  const dd = parseInt(chars[9] + chars[10], 10);
  let day: number;
  if (dd >= 1 && dd <= 31) {
    day = dd;
  } else if (dd >= 41 && dd <= 71) {
    day = dd - 40;
  } else {
    return false;
  }
  const maxDays = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > maxDays[month - 1]) return false;

  // Place of birth: letter among A-I, L, M, Z, then three digits
  if ("ABCDEFGHILMZ".indexOf(chars[11]) < 0) return false;

  // Check character
  const ODD = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23];
  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const c = chars[i];
    const idx = isDigit(c) ? c.charCodeAt(0) - 48 : c.charCodeAt(0) - 65;
    if (idx < 0 || idx > 25) return false;
    if (i % 2 === 0) {
      // 1st, 3rd, ... 15th characters (odd positions) use the odd table
      sum += ODD[idx];
    } else {
      sum += idx;
    }
  }
  const expected = String.fromCharCode(65 + (sum % 26));
  return chars[15] === expected;
}

export function solve(id: string): boolean {
  if (typeof id !== 'string') return false;

  // Heavy lifting: format and library-level check for cs-CZ.
  if (!lib.isTaxID(id, 'cs-CZ')) return false;

  // Strict shape: YYMMDD, optional slash, then 3 or 4 digits.
  const m = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!m) return false;

  const yy = Number(m[1]);
  let mm = Number(m[2]);
  const dd = Number(m[3]);
  const tail = m[4];
  const digits = m[1] + m[2] + m[3] + tail; // 9 or 10 digits, no slash

  // Year
  let year: number;
  if (tail.length === 4) {
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  } else {
    // Pre-1954 numbers: 3 digits, YY must be below 54, and not "000".
    if (yy >= 54 || tail === '000') return false;
    year = 1900 + yy;
  }

  // Month: women have +50; from 2004 on, +20 may also be added.
  if (mm > 50) mm -= 50;
  if (mm > 20) {
    if (year < 2004) return false;
    mm -= 20;
  }
  if (mm < 1 || mm > 12) return false;

  // Date must exist.
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  // Divisibility by 11 for 10-digit numbers.
  if (digits.length === 10) {
    const whole = Number(digits);
    if (whole % 11 === 0) return true;

    const first9 = Number(digits.slice(0, 9));
    const last = digits[9];
    if (year < 1986 && first9 % 11 === 10 && last === '0') return true;

    return false;
  }

  return true;
}

