// tax-ID checker. Its default locale, 'en-US', expects US EIN formats, and it
// has no Romanian CNP century, date, or check-digit rules, so it cannot
// validate a CNP. All checks are implemented below with the standard library.

export function solve(cnp: string): boolean {
  // Exactly 13 ASCII digits.
  if (!/^\d{13}$/.test(cnp)) return false;

  // Special case: accepted without further checks.
  if (cnp.startsWith("9000")) return true;

  const first = cnp.charCodeAt(0) - 48;
  const yy = Number(cnp.substring(1, 3));
  const mm = Number(cnp.substring(3, 5));
  const dd = Number(cnp.substring(5, 7));

  // Determine the full year when the first digit defines a century.
  let fullYear: number | null;
  switch (first) {
    case 1:
    case 2:
      fullYear = 1900 + yy;
      break;
    case 3:
    case 4:
      fullYear = 1800 + yy;
      break;
    case 5:
    case 6:
      fullYear = 2000 + yy;
      break;
    default:
      // 0, 7, 8, 9: two-digit year only.
      fullYear = null;
  }

  const isLeapFull = (y: number): boolean =>
    (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;

  const leap = fullYear !== null ? isLeapFull(fullYear) : yy % 4 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  // Date must exist.
  if (mm < 1 || mm > 12) return false;
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  // Check digit.
  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += (cnp.charCodeAt(i) - 48) * weights[i];
  }
  let remainder = sum % 11;
  if (remainder === 10) remainder = 1;

  return remainder === cnp.charCodeAt(12) - 48;
}

export function solve(hetu: string): boolean {
  // Structure: DDMMYY, century sign (+, -, A, or a), 3-digit individual number,
  // and an upper-case check character from the allowed set.
  const m = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})([0-9A-FHJ-NPR-Y])$/.exec(hetu);
  if (m === null) {
    return false;
  }

  const day = Number(m[1]);
  const month = Number(m[2]);
  const yy = Number(m[3]);
  const century = m[4].toUpperCase(); // 'a' is accepted as 'A'

  // Century sign determines the base year: + = 1800s, - = 1900s, A = 2000s.
  const base = century === '+' ? 1800 : century === '-' ? 1900 : 2000;
  const year = base + yy;

  // The date must exist (Gregorian leap-year rules).
  if (month < 1 || month > 12) {
    return false;
  }
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > daysInMonth[month - 1]) {
    return false;
  }

  // Normalize the century sign so the library's regex and check see a canonical form.
  const normalized = `${m[1]}${m[2]}${m[3]}${century}${m[5]}${m[6]}`;

  // Delegate the format and check-character verification to the library.
  return lib.isTaxID(normalized, 'fi-FI');
}

