  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += digits[i] * weights[i];
  }
  let remainder = sum % 11;
  if (remainder === 10) {
    remainder = 1;
  }

  return remainder === digits[12];
}

export function solve(hetu: string): boolean {
  const match = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})([0-9A-FHJKLMNPRSTUVWXY])$/.exec(hetu);
  if (!match) {
    return false;
  }

  const dayStr = match[1];
  const monthStr = match[2];
  const yearStr = match[3];
  const sign = match[4];
  const individual = match[5];
  const checkChar = match[6];

  const day = Number(dayStr);
  const month = Number(monthStr);
  const yy = Number(yearStr);

  const centuryBase = sign === "+" ? 1800 : sign === "-" ? 1900 : 2000;
  const year = centuryBase + yy;

  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (month < 1 || month > 12) {
    return false;
  }
  if (day < 1 || day > daysInMonth[month - 1]) {
    return false;
  }

  const CHECK_CHARS = "0123456789ABCDEFHJKLMNPRSTUVWXY";
  const number = Number(dayStr + monthStr + yearStr + individual);
  const expected = CHECK_CHARS[number % 31];

  return expected === checkChar;
}

export function solve(id: string): boolean {
  const match = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!match) return false;

  const yy = parseInt(match[1], 10);
  let mm = parseInt(match[2], 10);
  const dd = parseInt(match[3], 10);
  const suffix = match[4];
  const hasFourDigitSuffix = suffix.length === 4;

  // Determine the full year
  let year: number;
  if (hasFourDigitSuffix) {
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  } else {
    // Numbers issued before 1954
    if (yy >= 54) return false;
    if (suffix === "000") return false;
    year = 1900 + yy;
  }

  // Month: remove 50 for women, then possibly 20 (only from 2004 on)
  if (mm > 50) mm -= 50;
  if (mm > 20) {
    if (year < 2004) return false;
    mm -= 20;
  }
  if (mm < 1 || mm > 12) return false;

  // Day must exist in that month/year
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  // Checksum applies only to 10-digit numbers
  if (hasFourDigitSuffix) {
    const digits = match[1] + match[2] + match[3] + suffix;
    const n = Number(digits);
    if (n % 11 === 0) return true;
    if (
      year < 1986 &&
      Number(digits.slice(0, 9)) % 11 === 10 &&
      digits[9] === "0"
    ) {
      return true;
    }
    return false;
  }

  return true;
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;
  const s = code.toUpperCase();
  if (s.length !== 16 || !/^[A-Z0-9]{16}$/.test(s)) return false;

  // Name codes: consonants (X counts as consonant when before a vowel),
  // then vowels, then X padding.
  const isNameCode = (part: string): boolean =>
    /^[A-Z]{3}$/.test(part) && /^[^AEIOU]*[AEIOU]*X*$/.test(part);
  if (!isNameCode(s.slice(0, 3)) || !isNameCode(s.slice(3, 6))) return false;

  // Omocodia: positions that must hold digits may hold L M N P Q R S T U V for 0-9.
  const OMO = "LMNPQRSTUV";
  const digitPositions = [6, 7, 9, 10, 12, 13, 14];
  const t: string[] = s.split("");
  for (const i of digitPositions) {
    const ch = s[i];
    let v: number;
    if (ch >= "0" && ch <= "9") {
      v = ch.charCodeAt(0) - 48;
    } else {
      v = OMO.indexOf(ch);
    }
    if (v < 0) return false;
    t[i] = String(v);
  }

  // Month letter.
  const MONTHS = "ABCDEHLMPRST";
  const mIdx = MONTHS.indexOf(s[8]);
  if (mIdx < 0) return false;
  const month = mIdx + 1;

  // Place of birth initial letter.
  if (!/^[ABCDEFGHILMZ]$/.test(s[11])) return false;

  // Day (women: +40).
  let day = Number(t[9]) * 10 + Number(t[10]);
  if (day > 40) {
    if (day > 71) return false;
    day -= 40;
  }
  if (day < 1 || day > 31) return false;

  // Two-digit year, leap years: divisible by 4 (00 included).
  const year = Number(t[6]) * 10 + Number(t[7]);
  let maxDay: number;
  if (month === 2) {
    maxDay = year % 4 === 0 ? 29 : 28;
  } else if (month === 4 || month === 6 || month === 9 || month === 11) {
    maxDay = 30;
  } else {
    maxDay = 31;
  }
  if (day > maxDay) return false;

  // Check letter.
  const ODD_LETTER = [
    1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20,
    11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23,
  ];
  const ODD_DIGIT = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21];

  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const c = t[i];
    const isDigit = c >= "0" && c <= "9";
    if (i % 2 === 0) {
      // Odd positions (1st, 3rd, ... 15th).
      sum += isDigit ? ODD_DIGIT[c.charCodeAt(0) - 48] : ODD_LETTER[c.charCodeAt(0) - 65];
    } else {
      // Even positions (2nd, 4th, ... 14th).
      sum += isDigit ? c.charCodeAt(0) - 48 : c.charCodeAt(0) - 65;
    }
  }
  const expected = String.fromCharCode(65 + (sum % 26));
  return s[15] === expected;
}

export function solve(cnp: string): boolean {
  // Exactly 13 ASCII digits.
  if (!/^\d{13}$/.test(cnp)) return false;

  // Special case: codes starting with 9000 are accepted without further checks.
  if (cnp.startsWith("9000")) return true;

  const d = cnp.split("").map(Number);

  const yy = d[1] * 10 + d[2];
  const mm = d[3] * 10 + d[4];
  const dd = d[5] * 10 + d[6];

  // Century from the first digit. For first digits 0, 7, 8, 9 the year is
  // checked on YY alone, so there is no full year and leap-ness is YY % 4 == 0.
  let leap: boolean;
  switch (d[0]) {
    case 1:
    case 2:
      leap = isGregorianLeap(1900 + yy);
      break;
    case 3:
    case 4:
      leap = isGregorianLeap(1800 + yy);
      break;
    case 5:
    case 6:
      leap = isGregorianLeap(2000 + yy);
      break;
    default:
      leap = yy % 4 === 0;
      break;
  }

  // Date must exist.
  if (mm < 1 || mm > 12) return false;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  // Check digit: weighted sum of the first 12 digits, mod 11; a remainder of 10 counts as 1.
  // The library's isTaxID is not used because its locale checks are not known to
  // implement these Romanian rules.
  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += d[i] * weights[i];
  }
  let check = sum % 11;
  if (check === 10) check = 1;

  return check === d[12];
}

function isGregorianLeap(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

