  // Normalize omocodia: positions holding digits may hold L..V instead.
  const norm: string[] = s.split('');
  for (const i of [6, 7, 9, 10, 12, 13, 14]) {
    const c = s[i];
    if (isDigit(c)) {
      norm[i] = c;
    } else {
      const k = OMOCODE.indexOf(c);
      if (k < 0) return false;
      norm[i] = String(k);
    }
  }

  // Month letter.
  const monthIdx = MONTH_LETTERS.indexOf(s[8]);
  if (monthIdx < 0) return false;

  // Place of birth: first character letter from the allowed set.
  if (!PLACE_LETTERS.includes(s[11])) return false;

  // Date validity.
  const yy = parseInt(norm[6] + norm[7], 10);
  let day = parseInt(norm[9] + norm[10], 10);
  if (day >= 41 && day <= 71) day -= 40;
  if (day < 1) return false;
  const maxDay = monthIdx === 1 && yy % 4 === 0 ? 29 : MONTH_DAYS[monthIdx];
  if (day > maxDay) return false;

  // Check letter over the first 15 characters, with omocode digits read as digits.
  const oddValue = (c: string): number =>
    isDigit(c) ? ODD_VALUES[c.charCodeAt(0) - 48] : ODD_VALUES[c.charCodeAt(0) - 65];
  const evenValue = (c: string): number =>
    isDigit(c) ? c.charCodeAt(0) - 48 : c.charCodeAt(0) - 65;

  let sum = 0;
  for (let i = 0; i < 15; i++) {
    // 0-based even index = 1-based odd position.
    sum += i % 2 === 0 ? oddValue(norm[i]) : evenValue(norm[i]);
  }
  const expected = String.fromCharCode(65 + (sum % 26));
  if (s[15] !== expected) return false;

  // Final structural/checksum check via the library on the digit-normalized code.
  return lib.isTaxID(norm.join(''), 'it-IT');
}

export function solve(hetu: string): boolean {
  if (typeof hetu !== 'string') {
    return false;
  }

  // DDMMYY, century sign, 3-digit individual number, check character.
  // Check characters: 0-9 and the letters ABCDEFHJKLMNPRSTUVWXY (upper case only).
  const match = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})([0-9ABCDEFHJKLMNPRSTUVWXY])$/.exec(hetu);
  if (match === null) {
    return false;
  }

  const day = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const shortYear = parseInt(match[3], 10);
  const sign = match[4];

  let century: number;
  switch (sign) {
    case '+':
      century = 1800;
      break;
    case '-':
      century = 1900;
      break;
    case 'A':
    case 'a':
      century = 2000;
      break;
    default:
      return false;
  }

  const year = century + shortYear;
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (month < 1 || month > 12) {
    return false;
  }
  if (day < 1 || day > daysInMonth[month - 1]) {
    return false;
  }

  // Normalize the century sign so the library sees the canonical form.
  const normalized = hetu.slice(0, 6) + (sign === 'a' ? 'A' : sign) + hetu.slice(7);

  // Delegate the check-character (mod 31) verification to the library.
  return lib.isTaxID(normalized, 'fi-FI');
}

