  const d = cnp.split("").map(Number);
  const first = d[0];
  const yy = d[1] * 10 + d[2];
  const mm = d[3] * 10 + d[4];
  const dd = d[5] * 10 + d[6];

  const isGregorianLeap = (y: number): boolean =>
    (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;

  let leap: boolean;
  if (first === 1 || first === 2) {
    leap = isGregorianLeap(1900 + yy);
  } else if (first === 3 || first === 4) {
    leap = isGregorianLeap(1800 + yy);
  } else if (first === 5 || first === 6) {
    leap = isGregorianLeap(2000 + yy);
  } else {
    // First digit 0, 7, 8, 9: check on two-digit year alone
    leap = yy % 4 === 0;
  }

  // Validate the date
  if (mm < 1 || mm > 12) return false;
  const maxDays = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > maxDays[mm - 1]) return false;

  // Check digit
  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += d[i] * weights[i];
  }
  let check = sum % 11;
  if (check === 10) check = 1;

  return check === d[12];
}

const CHECK_CHARS = "0123456789ABCDEFHJKLMNPRSTUVWXY";

