export function solve(code: string): boolean {
  if (typeof code !== 'string' || code.length !== 16) return false;
  const s = code.toUpperCase();

  // Format check (lengths, character classes, omocodia positions) via the library.
  if (!lib.isTaxID(s, 'it-IT')) return false;

  const LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const OMO = 'LMNPQRSTUV';
  const VOWELS = 'AEIOU';
  const MONTHS = 'ABCDEHLMPRST';
  const PLACE_FIRST = 'ABCDEFGHILMZ';
  // Odd-position values, indexed by letter index (A=0..Z=25); digits 0-9 use the same table.
  const ODD = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23];
  const DIGIT_POS = [6, 7, 9, 10, 12, 13, 14];

  // Name code: consonants, then vowels, then X padding.
  const validName = (part: string): boolean => {
    let seenVowel = false;
    let padding = false;
    for (const c of part) {
      if (padding) {
        if (c !== 'X') return false;
        continue;
      }
      if (VOWELS.indexOf(c) >= 0) {
        seenVowel = true;
      } else if (c === 'X') {
        if (seenVowel) padding = true;
      } else if (seenVowel) {
        return false;
      }
    }
    return true;
  };

  if (!validName(s.slice(0, 3)) || !validName(s.slice(3, 6))) return false;

  // Decode digit positions (digits or omocodia letters).
  const digits: { [pos: number]: number } = {};
  for (const i of DIGIT_POS) {
    const c = s[i];
    let d: number;
    if (c >= '0' && c <= '9') {
      d = c.charCodeAt(0) - 48;
    } else {
      d = OMO.indexOf(c);
    }
    if (d < 0) return false;
    digits[i] = d;
  }

  // Month.
  const monthIdx = MONTHS.indexOf(s[8]);
  if (monthIdx < 0) return false;
  const month = monthIdx + 1;

  // Year and day.
  const year = digits[6] * 10 + digits[7];
  const rawDay = digits[9] * 10 + digits[10];
  if (!((rawDay >= 1 && rawDay <= 31) || (rawDay >= 41 && rawDay <= 71))) return false;
  const day = rawDay > 40 ? rawDay - 40 : rawDay;

  const leap = year % 4 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day > daysInMonth[month - 1]) return false;

  // Place of birth.
  if (PLACE_FIRST.indexOf(s[11]) < 0) return false;

  // Check character over the first 15 characters.
  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const v = DIGIT_POS.indexOf(i) >= 0 ? digits[i] : LETTERS.indexOf(s[i]);
    if (v < 0) return false;
    sum += i % 2 === 0 ? ODD[v] : v;
  }
  return LETTERS[sum % 26] === s[15];
}

export function solve(code: string): boolean {
  if (typeof code !== "string" || code.length !== 16) return false;
  const s = code.toUpperCase();

  const isLetter = (c: string): boolean => c.length === 1 && c >= "A" && c <= "Z";
  const VOWELS = "AEIOU";
  const OMOCODIA = "LMNPQRSTUV"; // L=0, M=1, ..., V=9
  const DIGIT_POSITIONS = [6, 7, 9, 10, 12, 13, 14];
  const isDigitPos = (i: number): boolean => DIGIT_POSITIONS.indexOf(i) >= 0;

  // Name code: consonants, then vowels, then X padding (X before any vowel is a consonant).
  const checkName = (start: number): boolean => {
    let state = 0; // 0 = consonant phase, 1 = vowel phase, 2 = X padding phase
    for (let i = start; i < start + 3; i++) {
      const c = s[i];
      if (!isLetter(c)) return false;
      if (state === 0) {
        if (VOWELS.indexOf(c) >= 0) state = 1;
        // consonants and X (before any vowel) stay in state 0
      } else if (state === 1) {
        if (VOWELS.indexOf(c) >= 0) {
          // more vowels allowed
        } else if (c === "X") {
          state = 2;
        } else {
          return false;
        }
      } else {
        if (c !== "X") return false;
      }
    }
    return true;
  };

  if (!checkName(0)) return false;
  if (!checkName(3)) return false;

  // Decode a character at a digit position: digit or omocodia letter.
  const digitOf = (i: number): number => {
    const c = s[i];
    const d = "0123456789".indexOf(c);
    if (d >= 0) return d;
    return OMOCODIA.indexOf(c); // -1 if invalid
  };

  for (const i of DIGIT_POSITIONS) {
    if (digitOf(i) < 0) return false;
  }

  // Year
  const year = digitOf(6) * 10 + digitOf(7);

  // Month letter
  const MONTH_LETTERS = "ABCDEHLMPRST";
  const monthIdx = MONTH_LETTERS.indexOf(s[8]);
  if (monthIdx < 0) return false;
  const month = monthIdx + 1;

  // Day
  let day = digitOf(9) * 10 + digitOf(10);
  if (day >= 41 && day <= 71) day -= 40;
  if (day < 1 || day > 31) return false;

  const daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const isLeap = year % 4 === 0;
  const maxDay = month === 2 && isLeap ? 29 : daysInMonth[month - 1];
  if (day > maxDay) return false;

  // Place of birth
  const PLACE_LETTERS = "ABCDEFGHILMZ";
  if (PLACE_LETTERS.indexOf(s[11]) < 0) return false;
  for (const i of [12, 13, 14]) {
    if (digitOf(i) < 0) return false;
  }

  // Check letter
  if (!isLetter(s[15])) return false;

  const ODD_DIGITS = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21];
  const ODD_LETTERS = [
    1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18,
    20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23,
  ];

  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const oddPosition = i % 2 === 0; // 1st, 3rd, ... 15th (1-indexed)
    if (isDigitPos(i)) {
      const v = digitOf(i);
      sum += oddPosition ? ODD_DIGITS[v] : v;
    } else {
      const v = s.charCodeAt(i) - 65;
      sum += oddPosition ? ODD_LETTERS[v] : v;
    }
  }

  const expected = String.fromCharCode(65 + (sum % 26));
  return expected === s[15];
}

