export function solve(hetu: string): boolean {
  const CHECK_CHARS = "0123456789ABCDEFHJKLMNPRSTUVWXY";

  const match = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})([0-9A-FHJ-NPR-Y])$/.exec(hetu);
  if (!match) {
    return false;
  }

  const dd = match[1];
  const mm = match[2];
  const yy = match[3];
  const sign = match[4];
  const nnn = match[5];
  const check = match[6];

  const century = sign === "+" ? 1800 : sign === "-" ? 1900 : 2000;
  const day = parseInt(dd, 10);
  const month = parseInt(mm, 10);
  const year = century + parseInt(yy, 10);

  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (month < 1 || month > 12) {
    return false;
  }
  if (day < 1 || day > daysInMonth[month - 1]) {
    return false;
  }

  const remainder = Number(dd + mm + yy + nnn) % 31;
  return CHECK_CHARS[remainder] === check;
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;
  const s = code.toUpperCase();
  if (s.length !== 16) return false;

  const isLetter = (c: string): boolean => c >= "A" && c <= "Z";
  const VOWELS = "AEIOU";
  const OMOCODE = "LMNPQRSTUV"; // L=0, M=1, ..., V=9
  const MONTHS = "ABCDEHLMPRST"; // January .. December
  const PLACE_FIRST = "ABCDEFGHILMZ";

  // Digit positions: year (6,7), day (9,10), place digits (12,13,14)
  const digitPos = [6, 7, 9, 10, 12, 13, 14];

  // Name check: consonants (X counts as consonant), then vowels, then X padding only
  const checkName = (part: string): boolean => {
    let phase = 0; // 0 = consonants, 1 = vowels seen, 2 = X padding
    for (let i = 0; i < part.length; i++) {
      const c = part[i];
      if (!isLetter(c)) return false;
      const isV = VOWELS.indexOf(c) >= 0;
      if (phase === 0) {
        if (isV) phase = 1;
      } else if (phase === 1) {
        if (c === "X") phase = 2;
        else if (!isV) return false;
      } else {
        if (c !== "X") return false;
      }
    }
    return true;
  };

  if (!checkName(s.slice(0, 3))) return false;
  if (!checkName(s.slice(3, 6))) return false;

  // Decode digit positions (digit or omocode letter)
  const val: number[] = new Array(16).fill(-1);
  for (const i of digitPos) {
    const c = s[i];
    let v = -1;
    if (c >= "0" && c <= "9") v = c.charCodeAt(0) - 48;
    else {
      const idx = OMOCODE.indexOf(c);
      if (idx >= 0) v = idx;
    }
    if (v < 0) return false;
    val[i] = v;
  }

  // Year
  const yy = val[6] * 10 + val[7];

  // Month
  const mIdx = MONTHS.indexOf(s[8]);
  if (mIdx < 0) return false;
  const month = mIdx + 1;

  // Day (women: +40)
  const rawDay = val[9] * 10 + val[10];
  let day: number;
  if (rawDay >= 1 && rawDay <= 31) day = rawDay;
  else if (rawDay >= 41 && rawDay <= 71) day = rawDay - 40;
  else return false;

  const leap = yy % 4 === 0;
  const dim = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > dim[month - 1]) return false;

  // Place of birth
  if (PLACE_FIRST.indexOf(s[11]) < 0) return false;

  // Check letter
  const ODD_LETTERS = [
    1, 0, 5, 7, 9, 13, 15, 17, 19, 21, // A-J (also digits 0-9)
    2, 4, 18, 20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23 // K-Z
  ];
  let total = 0;
  for (let i = 0; i < 15; i++) {
    let v: number;
    if (digitPos.indexOf(i) >= 0) {
      v = val[i];
    } else {
      if (!isLetter(s[i])) return false;
      v = s.charCodeAt(i) - 65;
    }
    if (i % 2 === 0) {
      // 1st, 3rd, ... 15th characters (odd positions in 1-based count)
      total += ODD_LETTERS[v];
    } else {
      // 2nd, 4th, ... 14th characters
      total += v;
    }
  }
  const expected = String.fromCharCode(65 + (total % 26));
  return s[15] === expected;
}

export function solve(code: string): boolean {
  if (typeof code !== 'string') return false;
  const s = code.toUpperCase();
  if (s.length !== 16) return false;

  const DIGIT_LETTERS = 'LMNPQRSTUV';
  const DIGIT_POS = [6, 7, 9, 10, 12, 13, 14];
  const isDigitChar = (c: string): boolean => c >= '0' && c <= '9';
  const isUpperLetter = (c: string): boolean => c >= 'A' && c <= 'Z';
  const isDigitPos = (i: number): boolean => DIGIT_POS.indexOf(i) !== -1;

  // Normalize: letters standing for digits become digits; all other positions must be letters.
  const chars: string[] = [];
  for (let i = 0; i < 16; i++) {
    let c = s[i];
    if (isDigitPos(i)) {
      if (!isDigitChar(c)) {
        const k = DIGIT_LETTERS.indexOf(c);
        if (k < 0) return false;
        c = String(k);
      }
    } else if (!isUpperLetter(c)) {
      return false;
    }
    chars.push(c);
  }

  // Name codes: consonants, then vowels, then X padding (X before a vowel is a consonant).
  const VOWELS = 'AEIOU';
  const validName = (a: string, b: string, c: string): boolean => {
    const seq = [a, b, c];
    let phase = 0; // 0: consonant phase, 1: vowel phase, 2: X padding phase
    for (let i = 0; i < seq.length; i++) {
      const ch = seq[i];
      const vowel = VOWELS.indexOf(ch) !== -1;
      if (phase === 0) {
        if (vowel) phase = 1;
      } else if (phase === 1) {
        if (ch === 'X') phase = 2;
        else if (!vowel) return false;
      } else {
        if (ch !== 'X') return false;
      }
    }
    return true;
  };
  if (!validName(chars[0], chars[1], chars[2])) return false;
  if (!validName(chars[3], chars[4], chars[5])) return false;

  // Year, month, day.
  const yy = Number(chars[6]) * 10 + Number(chars[7]);
  const monthIdx = 'ABCDEHLMPRST'.indexOf(chars[8]);
  if (monthIdx < 0) return false;
  const month = monthIdx + 1;

  const raw = Number(chars[9]) * 10 + Number(chars[10]);
  let day: number;
  if (raw >= 41 && raw <= 71) day = raw - 40;
  else if (raw >= 1 && raw <= 31) day = raw;
  else return false;

  const leap = yy % 4 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day > daysInMonth[month - 1]) return false;

  // Place of birth: letter among A-I, L, M, Z followed by three digits (or omocode letters).
  if ('ABCDEFGHILMZ'.indexOf(chars[11]) === -1) return false;

  // Check letter.
  const ODD = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23];
  const value = (c: string): number =>
    isDigitChar(c) ? c.charCodeAt(0) - 48 : c.charCodeAt(0) - 65;
  let sum = 0;
  for (let i = 0; i < 15; i++) {
    if (i % 2 === 0) {
      // 1-based odd position
      sum += ODD[value(chars[i])];
    } else {
      // 1-based even position
      sum += value(chars[i]);
    }
  }
  const expected = String.fromCharCode(65 + (sum % 26));
  if (expected !== chars[15]) return false;

  // Delegate the final format/consistency check to the library with the digit-normalized code.
  return lib.isTaxID(chars.join(''), 'it-IT');
}

export function solve(cnp: string): boolean {
  // Note: lib.isTaxID is not used. Its definition only dispatches by locale to
  // taxIdFormat/taxIdCheck tables, and nothing in the shown code provides a
  // Romanian CNP format or check. Calling it with a Romanian locale would either
  // throw or validate against the wrong rules, so the CNP logic is implemented here.

  if (!/^\d{13}$/.test(cnp)) return false;

  if (cnp.startsWith("9000")) return true;

  const digits: number[] = [];
  for (let i = 0; i < 13; i++) digits.push(cnp.charCodeAt(i) - 48);

  const first = digits[0];
  const yy = Number(cnp.slice(1, 3));
  const mm = Number(cnp.slice(3, 5));
  const dd = Number(cnp.slice(5, 7));

  let leap: boolean;
  if (first >= 1 && first <= 6) {
    let year: number;
    if (first === 1 || first === 2) year = 1900 + yy;
    else if (first === 3 || first === 4) year = 1800 + yy;
    else year = 2000 + yy;
    leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  } else {
    // First digit 0, 7, 8, 9: check on the two-digit year alone.
    leap = yy % 4 === 0;
  }

  if (mm < 1 || mm > 12) return false;

  const monthDays = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > monthDays[mm - 1]) return false;

  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) sum += digits[i] * weights[i];
  let check = sum % 11;
  if (check === 10) check = 1;

  return check === digits[12];
}

export function solve(cnp: string): boolean {
  if (!/^[0-9]{13}$/.test(cnp)) return false;

  // Codes starting with 9000 are accepted without further checks.
  if (cnp.startsWith("9000")) return true;

  const d = cnp.split("").map(Number);
  const century = d[0];
  const yy = d[1] * 10 + d[2];
  const mm = d[3] * 10 + d[4];
  const dd = d[5] * 10 + d[6];

  let isLeap: boolean;
  if (century >= 1 && century <= 6) {
    let fullYear: number;
    if (century === 1 || century === 2) fullYear = 1900 + yy;
    else if (century === 3 || century === 4) fullYear = 1800 + yy;
    else fullYear = 2000 + yy;
    isLeap = (fullYear % 4 === 0 && fullYear % 100 !== 0) || fullYear % 400 === 0;
  } else {
    // First digit 0, 7, 8, 9: check on the two-digit year alone.
    isLeap = yy % 4 === 0;
  }

  if (mm < 1 || mm > 12) return false;

  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  // Check digit.
  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += d[i] * weights[i];
  }
  let check = sum % 11;
  if (check === 10) check = 1;

  return check === d[12];
}

export function solve(hetu: string): boolean {
  if (typeof hetu !== 'string') return false;

  // Accept lowercase century sign 'a' by normalizing it to 'A'
  const s = hetu.length === 11 && hetu[6] === 'a'
    ? hetu.slice(0, 6) + 'A' + hetu.slice(7)
    : hetu;

  // Format: DDMMYY, century sign, 3-digit individual number, check character
  if (!/^\d{6}[+\-A]\d{3}[0-9ABCDEFHJKLMNPRSTUVWXY]$/.test(s)) return false;

  const dd = Number(s.slice(0, 2));
  const mm = Number(s.slice(2, 4));
  const yy = Number(s.slice(4, 6));

  const sign = s[6];
  const base = sign === '+' ? 1800 : sign === '-' ? 1900 : 2000;
  const year = base + yy;

  // Validate that the date exists
  if (mm < 1 || mm > 12) return false;
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  // Check character: 9-digit number DDMMYYZZZ mod 31
  const chars = '0123456789ABCDEFHJKLMNPRSTUVWXY';
  const num = Number(s.slice(0, 6) + s.slice(7, 10));
  const expected = chars[num % 31];
  if (s[10] !== expected) return false;

  // Delegate to the library's Finnish tax ID validation
  return lib.isTaxID(s, 'fi-FI');
}

export function solve(id: string): boolean {
  const match = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!match) return false;

  const yy = Number(match[1]);
  let mm = Number(match[2]);
  const dd = Number(match[3]);
  const tail = match[4];
  const digits = match[1] + match[2] + match[3] + tail;

  // Determine full year
  let year: number;
  if (tail.length === 4) {
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  } else {
    // 3-digit suffix: issued before 1954
    if (yy >= 54) return false;
    if (tail === "000") return false;
    year = 1900 + yy;
  }

  // Determine actual month (women +50, and +20 allowed from 2004 on)
  if (mm > 50) mm -= 50;
  if (mm > 20) {
    if (year < 2004) return false;
    mm -= 20;
  }
  if (mm < 1 || mm > 12) return false;

  // Validate day
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  // Modulo 11 check for 10-digit numbers
  if (tail.length === 4) {
    let r9 = 0;
    for (let i = 0; i < 9; i++) {
      r9 = (r9 * 10 + (digits.charCodeAt(i) - 48)) % 11;
    }
    const last = digits.charCodeAt(9) - 48;
    const full = (r9 * 10 + last) % 11;

    if (full === 0) return true;
    if (year < 1986 && r9 === 10 && last === 0) return true;
    return false;
  }

  return true;
}

export function solve(id: string): boolean {
  if (typeof id !== 'string') return false;
  if (!/^\d{6}\/?(\d{3}|\d{4})$/.test(id)) return false;

  const digits = id.replace('/', '');
  const yy = Number(digits.slice(0, 2));
  let month = Number(digits.slice(2, 4));
  const day = Number(digits.slice(4, 6));
  const tail = digits.slice(6);

  // Year
  let year: number;
  if (tail.length === 4) {
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  } else {
    // Numbers issued before 1954: YY must be below 54, serial must not be 000
    if (yy >= 54 || tail === '000') return false;
    year = 1900 + yy;
  }

  // Month: +50 for women, +20 allowed only from 2004 on
  if (month > 50) month -= 50;
  if (month > 20) {
    if (year < 2004) return false;
    month -= 20;
  }
  if (month < 1 || month > 12) return false;

  // Day must exist in that month
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > daysInMonth[month - 1]) return false;

  // 10-digit numbers: divisibility by 11, with the pre-1986 exception
  if (digits.length === 10) {
    const first9 = Number(digits.slice(0, 9));
    const exception = year < 1986 && first9 % 11 === 10 && digits[9] === '0';
    if (!exception) {
      if (Number(digits) % 11 !== 0) return false;
      if (!lib.isTaxID(digits, 'cs-CZ')) return false;
    }
  }

  return true;
}

export function solve(hetu: string): boolean {
  const CHECK_CHARS = "0123456789ABCDEFHJKLMNPRSTUVWXY";

  const match = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})(.)$/.exec(hetu);
  if (!match) {
    return false;
  }

  const dd = match[1];
  const mm = match[2];
  const yy = match[3];
  const sign = match[4];
  const zzz = match[5];
  const check = match[6];

  const day = Number(dd);
  const month = Number(mm);
  const shortYear = Number(yy);

  let centuryBase: number;
  if (sign === "+") {
    centuryBase = 1800;
  } else if (sign === "-") {
    centuryBase = 1900;
  } else {
    centuryBase = 2000;
  }
  const year = centuryBase + shortYear;

  if (month < 1 || month > 12) {
    return false;
  }

  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (day < 1 || day > daysInMonth[month - 1]) {
    return false;
  }

  const remainder = Number(dd + mm + yy + zzz) % 31;
  return CHECK_CHARS[remainder] === check;
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;
  const s = code.toUpperCase();
  if (!/^[A-Z0-9]{16}$/.test(s)) return false;

  const VOWELS = "AEIOU";
  const DIGIT_LETTERS = "LMNPQRSTUV";
  const MONTH_LETTERS = "ABCDEHLMPRST";
  const PLACE_LETTERS = "ABCDEFGHILMZ";

  const isDigit = (c: string): boolean => c >= "0" && c <= "9";

  // Validates a 3-letter name code (surname or given name).
  const validName = (part: string): boolean => {
    if (!/^[A-Z]{3}$/.test(part)) return false;
    // state 0: consonants (X counts as consonant here)
    // state 1: vowels seen
    // state 2: X padding seen after vowels
    let state = 0;
    for (const c of part) {
      if (state === 0) {
        if (VOWELS.includes(c)) state = 1;
      } else if (state === 1) {
        if (VOWELS.includes(c)) continue;
        if (c === "X") {
          state = 2;
          continue;
        }
        return false;
      } else {
        if (c !== "X") return false;
      }
    }
    return true;
  };

  if (!validName(s.slice(0, 3))) return false;
  if (!validName(s.slice(3, 6))) return false;

  // Normalize digit positions (year, day, place digits).
  const chars = s.split("");
  const digitPositions = [6, 7, 9, 10, 12, 13, 14];
  for (const p of digitPositions) {
    const c = chars[p];
    let v: number;
    if (isDigit(c)) {
      v = c.charCodeAt(0) - 48;
    } else {
      v = DIGIT_LETTERS.indexOf(c);
      if (v < 0) return false;
    }
    chars[p] = String(v);
  }

  // Month
  const monthIdx = MONTH_LETTERS.indexOf(chars[8]);
  if (monthIdx < 0) return false;
  const month = monthIdx + 1;

  // Year
  const yy = parseInt(chars[6] + chars[7], 10);
  const leap = yy % 4 === 0;

  // Day (women: +40)
  let dd = parseInt(chars[9] + chars[10], 10);
  if (dd >= 41 && dd <= 71) dd -= 40;
  if (dd < 1 || dd > 31) return false;

  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd > daysInMonth[month - 1]) return false;

  // Place of birth
  if (!PLACE_LETTERS.includes(chars[11])) return false;

  // Check letter
  const oddDigits = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21];
  const oddLetters = [
    1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18,
    20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23,
  ];

  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const c = chars[i];
    const isOdd = i % 2 === 0; // 1st, 3rd, ... 15th characters
    if (isDigit(c)) {
      const v = c.charCodeAt(0) - 48;
      sum += isOdd ? oddDigits[v] : v;
    } else {
      const v = c.charCodeAt(0) - 65;
      sum += isOdd ? oddLetters[v] : v;
    }
  }

  const expected = String.fromCharCode(65 + (sum % 26));
  return expected === chars[15];
}

export function solve(code: string): boolean {
  if (typeof code !== 'string') return false;
  const s = code.toUpperCase();
  if (!/^[A-Z0-9]{16}$/.test(s)) return false;

  const chars = s.split('');
  const OMO = 'LMNPQRSTUV';
  const DIGIT_POS = [6, 7, 9, 10, 12, 13, 14];
  const isLetter = (c: string) => /^[A-Z]$/.test(c);
  const isDigit = (c: string) => /^[0-9]$/.test(c);
  const VOWELS = 'AEIOU';

  // Name codes (positions 0-2 surname, 3-5 given name): letters only,
  // consonants, then vowels, then X padding, with the stated ordering rules.
  const checkName = (start: number): boolean => {
    let seenVowel = false;
    let seenX = false;
    for (let i = start; i < start + 3; i++) {
      const c = chars[i];
      if (!isLetter(c)) return false;
      if (seenX) {
        if (c !== 'X') return false;
      } else if (seenVowel) {
        if (VOWELS.includes(c)) {
          // vowel continues the vowel run
        } else if (c === 'X') {
          seenX = true;
        } else {
          return false;
        }
      } else {
        if (VOWELS.includes(c)) {
          seenVowel = true;
        }
        // consonants (including X before any vowel) are fine
      }
    }
    return true;
  };

  if (!checkName(0) || !checkName(3)) return false;

  // Decode omocodia: letters standing for digits in the 7 digit positions.
  for (const i of DIGIT_POS) {
    const c = chars[i];
    if (isDigit(c)) continue;
    const idx = OMO.indexOf(c);
    if (idx < 0) return false;
    chars[i] = String(idx);
  }

  // Month letter.
  const MONTHS = 'ABCDEHLMPRST';
  const mIdx = MONTHS.indexOf(chars[8]);
  if (mIdx < 0) return false;
  const month = mIdx + 1;

  // Place of birth: first char a letter from the allowed set, rest digits.
  if (!'ABCDEFGHILMZ'.includes(chars[11])) return false;
  if (!isDigit(chars[12]) || !isDigit(chars[13]) || !isDigit(chars[14])) return false;

  // Check letter.
  if (!isLetter(chars[15])) return false;

  // Date validity.
  const year = parseInt(chars[6] + chars[7], 10);
  const rawDay = parseInt(chars[9] + chars[10], 10);
  let day: number;
  if (rawDay >= 41 && rawDay <= 71) {
    day = rawDay - 40;
  } else if (rawDay >= 1 && rawDay <= 31) {
    day = rawDay;
  } else {
    return false;
  }
  const leap = year % 4 === 0;
  const maxDay = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day > maxDay[month - 1]) return false;

  // Normalized string with digits in place.
  const n = chars.join('');

  // Check character computation.
  const ODD_DIGIT = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21];
  const ODD_LETTER = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20, 11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23];
  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const c = n[i];
    if (isDigit(c)) {
      const v = c.charCodeAt(0) - 48;
      sum += i % 2 === 0 ? ODD_DIGIT[v] : v;
    } else {
      const v = c.charCodeAt(0) - 65;
      sum += i % 2 === 0 ? ODD_LETTER[v] : v;
    }
  }
  const expected = String.fromCharCode(65 + (sum % 26));
  if (expected !== n[15]) return false;

  // Delegate the standard-format and checksum validation to the library
  // on the normalized (digit-only) form.
  return lib.isTaxID(n, 'it-IT');
}

export function solve(cnp: string): boolean {
  // Note: lib.isTaxID is not used. It is a tax-ID checker whose default locale
  // (en-US) expects a different format, and it has no CNP date or check-digit logic.
  if (!/^\d{13}$/.test(cnp)) return false;

  if (cnp.startsWith("9000")) return true;

  const digits = cnp.split("").map((c) => c.charCodeAt(0) - 48);
  const first = digits[0];
  const yy = digits[1] * 10 + digits[2];
  const mm = digits[3] * 10 + digits[4];
  const dd = digits[5] * 10 + digits[6];

  const isGregorianLeap = (y: number): boolean =>
    (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;

  let leap: boolean;
  if (first === 1 || first === 2) {
    leap = isGregorianLeap(1900 + yy);
  } else if (first === 3 || first === 4) {
    leap = isGregorianLeap(1800 + yy);
  } else if (first === 5 || first === 6) {
    leap = isGregorianLeap(2000 + yy);
  } else {
    // First digit 0, 7, 8, 9: decide on the two-digit year alone.
    leap = yy % 4 === 0;
  }

  const monthDays = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (mm < 1 || mm > 12) return false;
  if (dd < 1 || dd > monthDays[mm - 1]) return false;

  const weights = [2, 7, 9, 1, 4, 6, 3, 5, 8, 2, 7, 9];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += digits[i] * weights[i];
  }
  let check = sum % 11;
  if (check === 10) check = 1;

  return check === digits[12];
}

export function solve(hetu: string): boolean {
  if (typeof hetu !== 'string') {
    return false;
  }

  // DDMMYY, century sign, 3-digit individual number, check character.
  // Check characters: 0-9 and A-Y without G, I, O, Q, U, Z (upper case only).
  const m = /^(\d{2})(\d{2})(\d{2})([+\-Aa])(\d{3})([0-9ABCDEFHJKLMNPRSTUVWXY])$/.exec(hetu);
  if (m === null) {
    return false;
  }

  const dd = m[1];
  const mm = m[2];
  const yy = m[3];
  const sign = m[4];
  const ind = m[5];
  const check = m[6];

  const centuryBase: Record<string, number> = { '+': 1800, '-': 1900, 'A': 2000, 'a': 2000 };
  const year = centuryBase[sign] + parseInt(yy, 10);
  const month = parseInt(mm, 10);
  const day = parseInt(dd, 10);

  // Verify the date exists (Gregorian calendar, including leap years).
  if (month < 1 || month > 12 || day < 1) {
    return false;
  }
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day > daysInMonth[month - 1]) {
    return false;
  }

  // Normalize the century sign to upper case before delegating to the library.
  const normalized = `${dd}${mm}${yy}${sign.toUpperCase()}${ind}${check}`;

  // The library performs format and check-character validation.
  return lib.isTaxID(normalized, 'fi-FI');
}

export function solve(id: string): boolean {
  // Note: lib.isTaxID is not used here. Its cs-CZ rules are not specified,
  // and this task's rules (the 2004 month rule, the 3-digit pre-1954 form,
  // and the pre-1986 mod-11 exception) must be applied exactly as written.

  const match = /^(\d{2})(\d{2})(\d{2})\/?(\d{3}|\d{4})$/.exec(id);
  if (!match) return false;

  const yy = Number(match[1]);
  const mm = Number(match[2]);
  const dd = Number(match[3]);
  const tail = match[4];

  // Year
  let year: number;
  if (tail.length === 4) {
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  } else {
    // 3 digits: issued before 1954
    if (yy >= 54 || tail === "000") return false;
    year = 1900 + yy;
  }

  // Month: remove 50 for women, then remove 20 (only from 2004 on)
  let month = mm;
  if (month > 50) month -= 50;
  if (month > 20) {
    if (year < 2004) return false;
    month -= 20;
  }
  if (month < 1 || month > 12) return false;

  // Day: the date must exist
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[month - 1]) return false;

  // Checksum: 10-digit numbers only
  if (tail.length === 4) {
    const digits = match[1] + match[2] + match[3] + tail;
    const whole = Number(digits);
    if (whole % 11 === 0) return true;
    if (
      year < 1986 &&
      Number(digits.slice(0, 9)) % 11 === 10 &&
      digits.charAt(9) === "0"
    ) {
      return true;
    }
    return false;
  }

  return true;
}

declare const lib: { isTaxID(str: string, locale?: string): boolean };

const MONTH_LETTERS = "ABCDEHLMPRST";
const PLACE_INITIALS = "ABCDEFGHILMZ";
const OMOCODE = "LMNPQRSTUV";
const DIGIT_POSITIONS = [6, 7, 9, 10, 12, 13, 14];

// Odd-position values, indexed by letter A..Z (digits 0..9 map to A..J).
const ODD_VALUES = [
  1, 0, 5, 7, 9, 13, 15, 17, 19, 21, 2, 4, 18, 20,
  11, 3, 6, 8, 12, 14, 16, 10, 22, 25, 24, 23,
];

/** Returns the digit value of a digit or omocode character, or undefined. */
function digitValue(c: string): number | undefined {
  if (/^[0-9]$/.test(c)) return Number(c);
  const idx = OMOCODE.indexOf(c);
  return idx >= 0 ? idx : undefined;
}

/** Validates a 3-letter name code: consonants, then vowels, then X padding. */
function validNameCode(part: string): boolean {
  if (!/^[A-Z]{3}$/.test(part)) return false;
  // 0 = consonant section, 1 = vowel section, 2 = X padding
  let state = 0;
  for (const c of part) {
    const vowel = "AEIOU".includes(c);
    if (state === 0) {
      // X (and other consonants) count as consonants here
      if (vowel) state = 1;
    } else if (state === 1) {
      if (c === "X") state = 2;
      else if (!vowel) return false;
    } else {
      if (c !== "X") return false;
    }
  }
  return true;
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;
  const s = code.toUpperCase();
  if (s.length !== 16 || !/^[A-Z0-9]{16}$/.test(s)) return false;

  // Format-level check delegated to the library (its format regex is a
  // necessary condition for everything validated below).
  if (!lib.isTaxID(s, "it-IT")) return false;

  // Name codes
  if (!validNameCode(s.slice(0, 3))) return false;
  if (!validNameCode(s.slice(3, 6))) return false;

  // Normalize digit positions (omocodes -> digits)
  const n = s.split("");
  for (const p of DIGIT_POSITIONS) {
    const v = digitValue(s[p]);
    if (v === undefined) return false;
    n[p] = String(v);
  }

  // Letter positions
  const monthIdx = MONTH_LETTERS.indexOf(s[8]);
  if (monthIdx < 0) return false;
  const month = monthIdx + 1;

  if (PLACE_INITIALS.indexOf(s[11]) < 0) return false;
  if (!/^[A-Z]$/.test(s[15])) return false;

  // Date
  const yy = Number(n[6]) * 10 + Number(n[7]);
  let day = Number(n[9]) * 10 + Number(n[10]);
  if (day >= 40) day -= 40; // female
  if (day < 1 || day > 31) return false;

  const leap = yy % 4 === 0; // 00 included
  let maxDay: number;
  if (month === 2) maxDay = leap ? 29 : 28;
  else if ([4, 6, 9, 11].includes(month)) maxDay = 30;
  else maxDay = 31;
  if (day > maxDay) return false;

  // Check letter over the first 15 characters (digits read as digits)
  let sum = 0;
  for (let i = 0; i < 15; i++) {
    const c = n[i];
    const isDigit = /^[0-9]$/.test(c);
    if (i % 2 === 0) {
      // 1st, 3rd, ... 15th characters (1-based odd)
      sum += isDigit ? ODD_VALUES[Number(c)] : ODD_VALUES[c.charCodeAt(0) - 65];
    } else {
      // 2nd, 4th, ... 14th characters (1-based even)
      sum += isDigit ? Number(c) : c.charCodeAt(0) - 65;
    }
  }
  const expected = String.fromCharCode(65 + (sum % 26));
  return s[15] === expected;
}
